def summ(T,name):
    sizes={k:sum(v.values()) for k,v in T.items()}
    chap={}
    for v in T.values():
        for r,n in v.items(): chap[r]=chap.get(r,0)+n
    print(name, sizes, "squad total", sum(sizes.values()), "by skill", chap)
    return sum(sizes.values())
a=summ(A,"Tribe A"); b=summ(B,"Tribe B")
coaches, leads = 3, 2
