paths=lambda n:n*(n-1)//2
for n in [7,8,a+1,b+1,total,100,150]: print("paths",n,paths(n))
# chapter lead load
def load(members, oneone_min=45, every_weeks=2, sync_h=1, other_h=3, week=37.5):
    reports=members-1
    o=reports*oneone_min/60/every_weeks
    tot=o+sync_h+other_h
    print(f"chapter {members}: reports {reports}, 1:1 h/wk {o:.2f}, total {tot:.2f} h/wk, {tot/week*100:.1f}% of {week}h, left for squad {week-tot:.2f}h ({(week-tot)/week*100:.1f}%)")
for m in [3,4,7,8,10,13,6]: load(m)
